INSERT INTO zinas (virsraksts, teksts, kategorija, izveidots, publicets) VALUES
('Pēdējais vakars — rīt mājup',
'Pienācis pēdējais vakars. Rīt ceļš ved mājup.\n\nDiena bija pelēka, un tagad līst, bet tas netraucē — pirts izkurta, suņi salīduši miegā, un mājiņā silti. Gar jūru šodien vēl viena pastaiga; smiltīs palika mūsu un suņu pēdas, ko vilnis drīz nolīdzinās.\n\nŠī nedēļa Vidzemes krastā bija tieši tāda, kādu to gribējās: klusa, gaiša, rudenīga. Jūra, meži, Cēsis un Limbaži, siltas pirtis un garas pastaigas. Paldies, Latvija — un paldies jums, kas sekojāt līdzi.\n\nBet Vidzemes krasts paliek sirdī — un reiz mēs te atgriezīsimies.\n\n⸻\n\nViimeinen ilta on koittanut. Huomenna tie vie kotiin.\n\nPäivä oli harmaa, ja nyt sataa, mutta se ei haittaa — sauna on lämmitetty, koirat painuneet uneen, ja mökissä on lämmin. Rannalla ehdittiin vielä yksi kävely; hiekkaan jäivät meidän ja koirien jäljet, jotka aalto pian tasoittaa.\n\nTämä viikko Vidzemen rannikolla oli juuri sellainen kuin toivoimme: hiljainen, kirkas, syksyinen. Meri, metsät, Cēsis ja Limbaži, lämpimät saunat ja pitkät kävelyt. Kiitos, Latvia — ja kiitos teille, jotka seurasitte matkaa.\n\nMutta Vidzemen rannikko jää sydämeen — ja tänne me vielä palaamme.',
'celojums',
'2026-10-23 18:45:00',
1);
